if (!function_exists('harmat_unified_sales_front_payload_20260513')) {
    function harmat_unified_sales_front_payload_20260513() {
        $cache_key = 'harmat_unified_sales_front_data_v3';
        $items = get_transient($cache_key);

        if (false === $items) {
            $posts = get_posts(array(
                'post_type' => 'property',
                'post_status' => 'publish',
                'posts_per_page' => -1,
                'orderby' => 'title',
                'order' => 'ASC',
                'fields' => 'ids',
            ));

            $labels = array(
                'current' => html_entity_decode('El&eacute;rhet&#337;', ENT_QUOTES, 'UTF-8'),
                'reserved' => 'Foglalva',
                'sold' => 'Eladva',
            );
            $items = array();

            foreach ($posts as $post_id) {
                $post_id = (int) $post_id;
                $status = get_post_meta($post_id, 'property_status', true);
                $under_offer = get_post_meta($post_id, 'property_under_offer', true);
                $sales_status = 'sold' === $status ? 'sold' : (!empty($under_offer) ? 'reserved' : 'current');
                $price = (int) get_post_meta($post_id, 'property_price', true);
                $sales_area = get_post_meta($post_id, '_harmat_sales_area', true);
                if ('' === $sales_area || null === $sales_area) {
                    $sales_area = get_post_meta($post_id, 'property_building_area', true);
                }
                $sales_area = (float) str_replace(',', '.', (string) $sales_area);
                $hide_price = 'yes' === get_post_meta($post_id, '_harmat_hide_front_price', true);
                $unit = trim((string) get_post_meta($post_id, 'property_address_sub_number', true));

                $items[$post_id] = array(
                    'id' => $post_id,
                    'title' => get_the_title($post_id),
                    'status' => $sales_status,
                    'statusLabel' => isset($labels[$sales_status]) ? $labels[$sales_status] : $labels['current'],
                    'price' => $hide_price ? 0 : $price,
                    'salesArea' => $sales_area,
                    'area' => $sales_area,
                    'sqmPrice' => (!$hide_price && $sales_area > 0) ? round($price / $sales_area) : 0,
                    'hidePrice' => $hide_price,
                    'rooms' => get_post_meta($post_id, 'property_rooms', true),
                    'bedrooms' => get_post_meta($post_id, 'property_bedrooms', true),
                    'building' => trim((string) get_post_meta($post_id, 'property_address_street', true)),
                    'floor' => trim((string) get_post_meta($post_id, 'property_address_street_number', true)),
                    'unit' => $unit,
                    'number' => $unit,
                    'terrace' => get_post_meta($post_id, 'property_land_area', true),
                    'url' => get_permalink($post_id),
                );
            }
            set_transient($cache_key, $items, 30 * MINUTE_IN_SECONDS);
        }

        return array(
            'items' => is_array($items) ? $items : array(),
            'apartments' => is_array($items) ? array_values($items) : array(),
            'source' => 'harmat-unified-sales-data-20260513',
        );
    }
}


