            if (!chip) { chip = document.createElement('span'); chip.className = 'harmat-front-price-chip'; box.appendChild(chip); }
            if (item.hidePrice) chip.dataset.harmatHidePrice = '1'; else delete chip.dataset.harmatHidePrice;
            chip.innerHTML = '<strong>' + priceLabel(item) + '</strong><small>' + sqmLabel(item) + '</small>';
            if (item.status === 'sold') card.querySelectorAll('.elementor-button-text').forEach(function(text){ text.textContent = 'Eladva'; });
          });
        });
      }
      document.addEventListener('DOMContentLoaded', applyCards);
